import torch


def run(x):
    return torch.is_nonzero(x)


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    # is_nonzero only accepts single-element tensors. Fill value 0 for the
    # zero-case workloads (encoded as multi-dim single-element shapes) and 1
    # for the non-zero-case workloads, mirroring the source pytest inputs.
    fill = 0 if len(shape) > 1 else 1
    return {"x": torch.full(shape, fill, dtype=dtype, device=device)}
